#ifdef SCRNSVR
uniform float uTime;
uniform vec2 uResolution;
uniform float speed;
uniform float scale;
uniform float crush;
uniform float pile;
uniform float lightAngle;
uniform float lightOrbit;
uniform float brightness;
uniform float saturation;
uniform vec3 highlightColor;
uniform vec3 color1;
uniform vec3 color2;
uniform vec3 background;
#else
#define uTime iTime
#define uResolution iResolution.xy
const float speed = 0.3;
const float scale = 1.2;
const float crush = 0.6;
const float pile = 0.5;
const float lightAngle = 40.0;
const float lightOrbit = 0.5;
const float brightness = 1.0;
const float saturation = 1.0;
const vec3 highlightColor = vec3(0.964706, 0.862745, 0.909804);
const vec3 color1 = vec3(0.490196, 0.141176, 0.266667);
const vec3 color2 = vec3(0.784314, 0.345098, 0.498039);
const vec3 background = vec3(0.070588, 0.027451, 0.050980);
#endif

// Match the collection's exposure and color controls; keep black at zero brightness.
vec4 finish(vec3 color) {
    color = 1.0 - exp(-max(color, vec3(0.0)) * brightness);
    float dither = fract(52.9829189 * fract(dot(gl_FragCoord.xy, vec2(0.06711056, 0.00583715))));
    color = clamp(color + (dither - 0.5) / 255.0 * min(brightness, 1.0), 0.0, 1.0);
    float luminance = dot(color, vec3(0.2126, 0.7152, 0.0722));
    return vec4(clamp(mix(vec3(luminance), color, saturation), 0.0, 1.0), 1.0);
}

float hash(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}

vec2 gradientAt(vec2 i) {
    float angle = hash(i) * 6.2831853;
    return vec2(cos(angle), sin(angle));
}

// Gradient noise in 0..1. Lighting reads its slope, and value noise's slope collapses
// along every lattice line, which would show as faint straight seams.
float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    vec2 u = f * f * f * (f * (f * 6.0 - 15.0) + 10.0);
    float a = dot(gradientAt(i), f);
    float b = dot(gradientAt(i + vec2(1.0, 0.0)), f - vec2(1.0, 0.0));
    float c = dot(gradientAt(i + vec2(0.0, 1.0)), f - vec2(0.0, 1.0));
    float d = dot(gradientAt(i + vec2(1.0, 1.0)), f - vec2(1.0, 1.0));
    return clamp(0.5 + 0.75 * mix(mix(a, b, u.x), mix(c, d, u.x), u.y), 0.0, 1.0);
}

// Folded fabric height: smooth swells plus creases whose sharpness follows Crush.
float fabric(vec2 q, float t) {
    vec2 warp = vec2(noise(q * 0.7 + vec2(t * 0.02, 3.1)), noise(q * 0.7 + vec2(8.2, -t * 0.015))) - 0.5;
    q += warp * 1.2;
    float height = 0.0;
    float amplitude = 0.55;
    for (int i = 0; i < 3; i++) {
        float n = noise(q);
        // A rounded crease: a hard abs() leaves slope breaks the sheen turns into sharp seams.
        float centered = n * 2.0 - 1.0;
        float ridge = 1.0 - sqrt(centered * centered + 0.012);
        height += amplitude * mix(n, ridge * ridge, crush);
        q = mat2(1.6, 1.2, -1.2, 1.6) * q + 11.7;
        amplitude *= 0.42;
    }
    return height;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 p = ((fragCoord / uResolution) - 0.5) * vec2(uResolution.x / uResolution.y, 1.0);
    float t = uTime * speed;
    vec2 q = p * 1.7 / scale;
    float e = 0.012;
    float h = fabric(q, t);
    vec2 slope = vec2(fabric(q + vec2(e, 0.0), t) - h, fabric(q + vec2(0.0, e), t) - h) / e;
    float relief = mix(0.7, 1.7, crush);
    vec3 normal = normalize(vec3(-slope * relief, 1.0));
    float light = radians(lightAngle) + t * lightOrbit * 0.15;
    vec3 toLight = normalize(vec3(cos(light), sin(light), 0.55));
    // Velvet: the pile catches light where it turns away from the viewer, strongest on the lit side.
    float facing = clamp(normal.z, 0.0, 1.0);
    float rim = pow(1.0 - facing, mix(5.0, 1.4, pile));
    vec2 tilt = normal.xy / max(length(normal.xy), 1e-4);
    float side = 0.25 + 0.75 * smoothstep(-0.3, 0.9, dot(tilt, toLight.xy));
    float sheen = clamp(rim * side * 3.2, 0.0, 1.6);
    float diffuse = clamp(dot(normal, toLight), 0.0, 1.0);
    vec3 color = mix(background, color1, 0.35 + 0.55 * diffuse);
    color += color2 * sheen * 0.95;
    color += highlightColor * pow(sheen / 1.6, 3.0) * 0.55;
    // Deep folds fall into shadow.
    color *= 0.65 + 0.35 * smoothstep(0.15, 0.75, h);
    fragColor = finish(color);
}

precision highp float;

#ifdef SCRNSVR
uniform float uTime;
uniform vec2 uResolution;

uniform float speed;
uniform float scale;
uniform float distortion;
uniform float softness;
uniform float glow;
uniform float brightness;
uniform vec3 color1; // deep shadow
uniform vec3 color2; // midtone
uniform vec3 color3; // highlight
uniform float saturation;

#else
#define uTime iTime
#define uResolution iResolution.xy

const float speed      = 0.1;
const float scale      = 1.0;
const float distortion = 0.65;
const float softness   = 0.55;
const float glow       = 0.8;
const float brightness = 1.15;
const vec3 color1 = vec3(0.023529, 0.070588, 0.109804);
const vec3 color2 = vec3(0.101961, 0.329412, 0.368627);
const vec3 color3 = vec3(1.000000, 0.690196, 0.388235);
const float saturation = 0.9;
#endif


mat2 rotate2D(float a) {
    float c = cos(a);
    float s = sin(a);

    return mat2(
         c, -s,
         s,  c
    );
}


float hash21(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);

    return fract(p.x * p.y);
}


/*
    Smooth pseudo-noise without texture sampling.
*/
float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);

    f = f * f * (3.0 - 2.0 * f);

    float a = hash21(i);
    float b = hash21(i + vec2(1.0, 0.0));
    float c = hash21(i + vec2(0.0, 1.0));
    float d = hash21(i + vec2(1.0, 1.0));

    return mix(
        mix(a, b, f.x),
        mix(c, d, f.x),
        f.y
    );
}


float fbm(vec2 p) {
    float value = 0.0;
    float amplitude = 0.5;

    for (int i = 0; i < 4; i++) {
        value += noise(p) * amplitude;

        p = rotate2D(0.47) * p * 2.02;
        amplitude *= 0.5;
    }

    return value;
}


/*
    Distance from a slowly undulating ribbon.
*/
float ribbon(
    vec2 p,
    float offset,
    float frequency,
    float phase,
    float t
) {
    float wave =
          0.32 * sin(p.x * frequency + phase + t * 0.18)
        + 0.12 * sin(p.x * frequency * 0.47 - phase + t * 0.11)
        + 0.05 * sin(p.x * 2.4 - t * 0.08);

    return abs(p.y - wave - offset);
}


void mainImage(
    out vec4 fragColor,
    in vec2 fragCoord
) {
    vec2 uv = fragCoord / uResolution;

    vec2 p = uv - 0.5;
    p.x *= uResolution.x / uResolution.y;

    p *= scale * 2.35;

    float t = uTime * speed;


    // --------------------------------------------
    // Large-scale organic coordinate deformation
    // --------------------------------------------

    vec2 warp;

    warp.x = fbm(
        p * 0.48 +
        vec2(t * 0.035, -t * 0.018)
    );

    warp.y = fbm(
        p * 0.43 +
        vec2(4.7, 2.1) +
        vec2(-t * 0.021, t * 0.025)
    );

    warp = warp * 2.0 - 1.0;

    vec2 q = p + warp * distortion * 0.42;


    // --------------------------------------------
    // Main flowing surfaces
    // --------------------------------------------

    float d1 = ribbon(
        q,
        -0.28,
        1.05,
        0.0,
        t
    );

    float d2 = ribbon(
        q,
        0.08,
        0.82,
        1.8,
        t * 0.83
    );

    float d3 = ribbon(
        q,
        0.47,
        0.67,
        3.6,
        t * 0.68
    );


    float width1 = mix(0.08, 0.34, softness);
    float width2 = mix(0.10, 0.42, softness);
    float width3 = mix(0.14, 0.52, softness);


    float band1 =
        exp(-d1 * d1 / max(0.001, width1 * width1));

    float band2 =
        exp(-d2 * d2 / max(0.001, width2 * width2));

    float band3 =
        exp(-d3 * d3 / max(0.001, width3 * width3));


    // --------------------------------------------
    // Broad atmospheric gradient
    // --------------------------------------------

    float atmosphere =
        0.5 +
        0.5 * sin(
            q.x * 0.52 -
            q.y * 0.75 +
            t * 0.07
        );

    atmosphere = smoothstep(
        0.05,
        0.95,
        atmosphere
    );


    float field =
          band1 * 0.68
        + band2 * 0.44
        + band3 * 0.22;

    field += atmosphere * 0.20;

    field = clamp(field, 0.0, 1.0);


    // --------------------------------------------
    // Palette
    // --------------------------------------------

    vec3 col = mix(
        color1,
        color2,
        smoothstep(0.0, 0.72, field)
    );

    float highlight =
        pow(max(band1, band2 * 0.85), 2.2);

    col = mix(
        col,
        color3,
        highlight * 0.68
    );


    // --------------------------------------------
    // Soft luminous edge
    // --------------------------------------------

    float edgeDistance =
        min(d1, min(d2, d3));

    float halo =
        exp(
            -edgeDistance * edgeDistance /
            max(0.001, 0.16 + softness * 0.32)
        );

    col += color3 *
           halo *
           glow *
           0.18;


    // --------------------------------------------
    // Subtle depth / vignette
    // --------------------------------------------

    float radial =
        length(
            (uv - 0.5) *
            vec2(
                uResolution.x / uResolution.y,
                1.0
            )
        );

    col *= 1.0 - radial * 0.16;


    // --------------------------------------------
    // Film-like micro grain to reduce banding
    // --------------------------------------------

    float grain =
        hash21(
            fragCoord +
            fract(t) * 137.0
        ) - 0.5;

    col += grain / 255.0 * 1.4;


    // --------------------------------------------
    // Exposure
    // --------------------------------------------

    col =
        1.0 -
        exp(
            -max(col, 0.0) *
            brightness
        );


    // --------------------------------------------
    // Saturation
    // --------------------------------------------

    float luminance =
        dot(
            col,
            vec3(0.2126, 0.7152, 0.0722)
        );

    col = mix(
        vec3(luminance),
        col,
        saturation
    );


    fragColor = vec4(
        clamp(col, 0.0, 1.0),
        1.0
    );
}

