    float core = exp(-distanceSquared / (radius * radius));
    float haloRadius = mix(0.015, 0.05, glow) * (0.6 + seed * 0.4);
    float halo = exp(-distanceSquared / (haloRadius * haloRadius)) * glow * 0.23;
