    float envelope = smoothstep(0.0, 0.18 * fadeDuration, life) * (1.0 - smoothstep(1.0 - 0.25 * fadeDuration, 1.0, life));
    float visibility = 1.0 - smoothstep(density * 32.0 - 1.0, density * 32.0, id);
    color += mix(color1, color2, seed) * (core + halo) * envelope * visibility;
  }
  float haze = 0.5 + 0.5 * sin((fragCoord / uResolution).x * 6.0 + sin((fragCoord / uResolution).y * 4.0 - t * 0.15) + t * 0.12);
  color += color1 * haze * hazeStrength * (1.0 - (fragCoord / uResolution).y);
  fragColor = vec4(1.0 - exp(-color * brightness), 1.0);
  float luminance = dot(fragColor.rgb, vec3(0.2126, 0.7152, 0.0722));
  fragColor.rgb = mix(vec3(luminance), fragColor.rgb, saturation);
