        float radius = max(px * 1.1, 0.0016 + 0.0024 * hash(cell + 9.7));
        float mote = exp(-dot(delta, delta) / (radius * radius));
        float lit = 0.12 + 1.6 * beams * reach;
        color += mix(color1, vec3(1.0), 0.3) * mote * lit * 0.8;
    }
    fragColor = finish(color);
}

precision highp float;

#ifdef SCRNSVR
uniform float uTime;
uniform vec2 uResolution;
uniform float speed;
uniform int pieces;
uniform float size;
uniform float travel;
uniform float turn;
uniform vec3 color1;
uniform vec3 color2;
uniform vec3 color3;
uniform vec3 background;
uniform float brightness;
uniform float saturation;
#else
#define uTime iTime
#define uResolution iResolution.xy
const float speed = 0.3;
const int pieces = 7;
const float size = 0.11;
const float travel = 0.8;
const float turn = 0.7;
const vec3 color1 = vec3(0.796078, 0.662745, 0.545098);
const vec3 color2 = vec3(0.713725, 0.560784, 0.623529);
const vec3 color3 = vec3(0.545098, 0.670588, 0.698039);
const vec3 background = vec3(0.168627, 0.188235, 0.254902);
const float brightness = 1.0;
const float saturation = 1.0;
#endif

// Static sub-byte dithering preserves broad gradients without temporal grain.
vec4 finish(vec3 color) {
  color = clamp(color * brightness, 0.0, 1.0);
  float dither = fract(52.9829189 * fract(dot(gl_FragCoord.xy, vec2(0.06711056, 0.00583715))));
  color = clamp(color + (dither - 0.5) / 255.0 * min(brightness, 1.0), 0.0, 1.0);
  float luminance = dot(color, vec3(0.2126, 0.7152, 0.0722));
  return vec4(clamp(mix(vec3(luminance), color, saturation), 0.0, 1.0), 1.0);
}

vec3 palette(float phase) {
  return mix(mix(color1, color2, smoothstep(0.0, 0.5, phase)), color3, smoothstep(0.5, 1.0, phase));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 aspect = uResolution / min(uResolution.x, uResolution.y);
  vec2 p = (fragCoord / uResolution - 0.5) * aspect;
  float t = uTime * speed;
  float aa = 1.5 / min(uResolution.x, uResolution.y);
  float rows = ceil(float(pieces) / 3.0);
  vec3 color = background;
  for (int i = 0; i < 9; i++) {
    if (i >= pieces) continue;
    float fi = float(i);
    float row = floor(fi / 3.0);
    float columns = min(3.0, float(pieces) - row * 3.0);
    vec2 center = aspect * vec2((mod(fi, 3.0) - (columns - 1.0) * 0.5) * 0.31,
      (row - (rows - 1.0) * 0.5) * 0.83 / rows);
    center += travel * 0.045 * vec2(sin(t * 0.21 + fi * 2.4), cos(t * 0.17 + fi));
    vec2 q = p - center;
    float a = fi * 0.57 + turn * 0.24 * sin(t * 0.19 + fi * 1.7);
    q = mat2(cos(a), -sin(a), sin(a), cos(a)) * q;
    float kind = mod(fi + row, 3.0);
    float distance;
    if (kind < 0.5) distance = max(max(-q.x - size, -q.y - size), (q.x + q.y) * 0.707107);
    else if (kind < 1.5) distance = max(abs(q.y) - size * 0.72, (abs(q.x) - size * 0.82 - q.y * 0.32) / 1.05);
    else distance = max(abs(q.y) - size * 0.65, (abs(q.x + q.y * 0.5) - size * 0.75) / 1.118034);
    float mask = 1.0 - smoothstep(-aa, aa, distance);
    vec3 tint = palette(kind * 0.5);
    tint *= 0.86 + 0.14 * smoothstep(-size, size, q.x + q.y * 0.4);
    color = mix(color, tint, mask);
  }
  fragColor = finish(color);
}

precision highp float;

#ifdef SCRNSVR
uniform float uTime;
uniform vec2 uResolution;
uniform float speed;
uniform float scale;
uniform float focus;
uniform float brightness;
uniform vec3 color1;
uniform vec3 color2;
uniform float saturation;
uniform int layers;
uniform float distortion;
uniform float complexity;
uniform float direction;
uniform float depthShading;
#else
#define uTime iTime
#define uResolution iResolution.xy
const float speed = 0.25;
const float scale = 1.0;
const float focus = 0.5;
const float brightness = 1.0;
const vec3 color1 = vec3(0.023529, 0.223529, 0.301961);
const vec3 color2 = vec3(0.443137, 0.898039, 0.815686);
const float saturation = 1.0;
const int layers = 3;
const float distortion = 0.7;
const float complexity = 0.5;
const float direction = 0.0;
const float depthShading = 1.0;
#endif

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 p = ((fragCoord / uResolution) - 0.5) * vec2(uResolution.x / uResolution.y, 1.0) * scale * 6.0;
  float rotation = radians(direction);
  p = mat2(cos(rotation), sin(rotation), -sin(rotation), cos(rotation)) * p;
  float t = uTime * speed;
  vec2 q = p + vec2(sin(p.y * 0.8 + t * 0.31), cos(p.x * 0.7 - t * 0.27)) * distortion;
  float light = 0.0;
  for (int i = 0; i < 4; i++) {
    if (i >= layers) continue;
    float layer = float(i);
    vec2 r = mat2(0.8, -0.6, 0.6, 0.8) * q;
    q = r + vec2(1.7, 2.3);
    float wave = sin(q.x * 1.6 + t * 0.4 + layer)
      + sin(q.y * 1.5 - t * 0.35)
      + complexity * sin((q.x + q.y) * 1.2 + t * 0.22);
    light += exp(-abs(wave) * mix(3.0, 9.0, focus)) / float(layers);
  }
  float depth = 0.75 + 0.25 * depthShading * sin(p.x * 0.35 + p.y * 0.4 + t * 0.15);
  vec3 color = color1 * depth + color2 * light * 0.85;
  float dither = fract(52.9829189 * fract(dot(gl_FragCoord.xy, vec2(0.06711056, 0.00583715))));
  fragColor = vec4(clamp((1.0 - exp(-color * brightness)) + (dither - 0.5) / 255.0 * min(brightness, 1.0), 0.0, 1.0), 1.0);
  float luminance = dot(fragColor.rgb, vec3(0.2126, 0.7152, 0.0722));
  fragColor.rgb = mix(vec3(luminance), fragColor.rgb, saturation);
}

precision highp float;

#ifdef SCRNSVR
uniform float uTime;
uniform vec2 uResolution;
uniform float speed;
uniform int layers;
uniform float waveHeight;
uniform float wavelength;
uniform float sway;
uniform vec3 color1;
uniform vec3 color2;
uniform vec3 color3;
uniform vec3 background;
uniform float brightness;
uniform float saturation;
#else
#define uTime iTime
#define uResolution iResolution.xy
const float speed = 0.3;
const int layers = 4;
const float waveHeight = 0.09;
const float wavelength = 1.0;
const float sway = 0.7;
const vec3 color1 = vec3(0.643137, 0.709804, 0.643137);
const vec3 color2 = vec3(0.862745, 0.784314, 0.654902);
const vec3 color3 = vec3(0.384314, 0.498039, 0.572549);
const vec3 background = vec3(0.909804, 0.874510, 0.811765);
const float brightness = 1.0;
const float saturation = 1.0;
#endif

// Static sub-byte dithering preserves broad gradients without temporal grain.
vec4 finish(vec3 color) {
  color = clamp(color * brightness, 0.0, 1.0);
  float dither = fract(52.9829189 * fract(dot(gl_FragCoord.xy, vec2(0.06711056, 0.00583715))));
  color = clamp(color + (dither - 0.5) / 255.0 * min(brightness, 1.0), 0.0, 1.0);
  float luminance = dot(color, vec3(0.2126, 0.7152, 0.0722));
  return vec4(clamp(mix(vec3(luminance), color, saturation), 0.0, 1.0), 1.0);
}

vec3 palette(float phase) {
  return mix(mix(color1, color2, smoothstep(0.0, 0.5, phase)), color3, smoothstep(0.5, 1.0, phase));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 p = fragCoord / uResolution - 0.5;
  float x = p.x * uResolution.x / min(uResolution.x, uResolution.y) / wavelength;
  float t = uTime * speed;
  float aa = 1.5 / uResolution.y;
  vec3 color = mix(background, background * 0.92, fragCoord.y / uResolution.y);
  for (int i = 0; i < 6; i++) {
    if (i >= layers) continue;
    float fi = float(i);
    float phase = fi / max(float(layers - 1), 1.0);
    float boundary = 0.20 - phase * 0.53
      + waveHeight * sin(x * 3.2 + fi * 1.3 + t * (0.16 + fi * 0.009))
      + waveHeight * 0.35 * cos(x * 5.1 - t * 0.12 + fi)
      + sway * 0.035 * sin(t * 0.20 + fi * 0.8);
    float mask = 1.0 - smoothstep(boundary - aa, boundary + aa, p.y);
    vec3 tint = palette(phase);
    tint *= 0.9 + 0.1 * smoothstep(-0.5, boundary, p.y);
    color = mix(color, tint, mask);
  }
  fragColor = finish(color);
}

effects.source:
precision highp float;
uniform sampler2D uInput;
uniform vec2 uResolution;
uniform float uTime;
uniform float intensity;
uniform float grain;
uniform float scanlines;
uniform float colorBleed;
uniform float tracking;
varying vec2 vUv;

// Keep every tap inside a texel center: odd sizes and WebGL1 NPOT targets
// behave exactly like larger displays, without wrapping or a dark border.
vec3 tapeSample(vec2 uv) {
  vec2 edge = 0.5 / max(uResolution, vec2(1.0));
  return texture2D(uInput, clamp(uv, edge, 1.0 - edge)).rgb;
}
float noise(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}
void main() {
  vec3 original = tapeSample(vUv);
  if (intensity <= 0.0) { gl_FragColor = vec4(original, 1.0); return; }
  vec2 size = max(uResolution, vec2(1.0));
  float frame = floor(uTime * 24.0);
  float row = floor(vUv.y * size.y);
  float bandPosition = fract(uTime * 0.073);
  float bandDistance = abs(vUv.y - bandPosition);
  float band = 1.0 - smoothstep(0.0, 0.035, bandDistance);
  float jitter = (noise(vec2(row, frame)) - 0.5) * 0.8;
  float drift = sin(row * 0.065 + uTime * 4.0) * band * 3.0;
  vec2 uv = vUv + vec2((jitter + drift) * tracking / size.x, 0.0);
  vec2 bleed = vec2((0.5 + band * 1.5) * colorBleed * 2.0 / size.x, 0.0);
  vec3 tape = tapeSample(uv);
  tape.r = tapeSample(uv + bleed).r;
  tape.b = tapeSample(uv - bleed).b;
  float lines = mod(row, 2.0);
  tape *= 1.0 - scanlines * 0.10 * lines;
  tape += (noise(floor(vUv * size) + vec2(frame * 13.0, frame * 7.0)) - 0.5) * grain * 0.10;
  tape += band * tracking * 0.025;
  gl_FragColor = vec4(mix(original, clamp(tape, 0.0, 1.0), intensity), 1.0);
}

precision highp float;
uniform sampler2D uInput;
uniform sampler2D uOriginal;
uniform vec2 uResolution;
uniform float intensity;
uniform float curvature;
uniform float maskStrength;
uniform float scanlines;
uniform float edgeFalloff;
varying vec2 vUv;
vec3 sampleImage(vec2 uv) {
  vec2 edge = 0.5 / max(uResolution, vec2(1.0));
  return texture2D(uInput, clamp(uv, edge, 1.0 - edge)).rgb;
}
void main() {
  vec2 size = max(uResolution, vec2(1.0));
  vec2 edge = 0.5 / size;
  vec3 original = texture2D(uOriginal, clamp(vUv, edge, 1.0 - edge)).rgb;
  vec2 p = vUv * 2.0 - 1.0;
  // The curvature scales relative to the screen, not a landscape-only circle.
  vec2 uv = 0.5 + p * (1.0 + curvature * 0.22 * dot(p, p)) * 0.5;
  vec3 color = sampleImage(uv);
  float stripe = mod(floor(vUv.x * size.x), 3.0);
  vec3 phosphor = stripe < 1.0 ? vec3(1.0, 0.65, 0.65) :
    (stripe < 2.0 ? vec3(0.65, 1.0, 0.65) : vec3(0.65, 0.65, 1.0));
  color *= mix(vec3(1.0), phosphor, maskStrength);
  color *= 1.0 - scanlines * 0.3 * mod(floor(vUv.y * size.y), 2.0);
  float rim = smoothstep(0.45, 1.35, length(p * vec2(0.8, 0.8)));
  color *= 1.0 - edgeFalloff * rim * 0.8;
  gl_FragColor = vec4(mix(original, clamp(color, 0.0, 1.0), intensity), 1.0);
}

precision highp float;
uniform sampler2D uInput;
uniform sampler2D uOriginal;
uniform vec2 uResolution;
uniform float uTime;
uniform float intensity;
uniform float grain;
uniform float warmth;
uniform float fade;
uniform float exposureDrift;
varying vec2 vUv;
float noise(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
void main() {
  vec2 size = max(uResolution, vec2(1.0));
  vec2 uv = clamp(vUv, 0.5 / size, 1.0 - 0.5 / size);
  vec3 original = texture2D(uOriginal, uv).rgb;
  vec3 color = texture2D(uInput, uv).rgb;
  color *= vec3(1.0 + warmth * 0.18, 1.0 + warmth * 0.025, 1.0 - warmth * 0.18);
  color += fade * 0.22 * (1.0 - color);
  // Slow exposure modulation is bounded to ten percent, never a flash.
  color *= 1.0 + exposureDrift * (0.065 * sin(uTime * 0.43 + 0.6) + 0.035 * sin(uTime * 0.19));
  float frame = floor(uTime * 24.0);
  color += (noise(floor(vUv * size) + vec2(frame * 17.0, frame * 31.0)) - 0.5) * grain * 0.16;
  gl_FragColor = vec4(mix(original, clamp(color, 0.0, 1.0), intensity), 1.0);
}

precision highp float;
uniform sampler2D uInput;
uniform sampler2D uOriginal;
uniform vec2 uResolution;
uniform float intensity;
uniform int pixelSize;
uniform float gridAspect;
varying vec2 vUv;
void main() {
  vec2 size = max(uResolution, vec2(1.0));
  vec2 edge = 0.5 / size;
  vec3 original = texture2D(uOriginal, clamp(vUv, edge, 1.0 - edge)).rgb;
  float aspect = sqrt(max(gridAspect, 0.01));
  vec2 block = max(vec2(1.0), float(pixelSize) * vec2(aspect, 1.0 / aspect));
  vec2 uv = (floor(vUv * size / block) + 0.5) * block / size;
  vec3 color = texture2D(uInput, clamp(uv, edge, 1.0 - edge)).rgb;
  gl_FragColor = vec4(mix(original, color, intensity), 1.0);
}

precision highp float;
uniform sampler2D uInput;
uniform sampler2D uOriginal;
uniform vec2 uResolution;
uniform float intensity;
uniform int patternSize;
uniform int levels;
uniform float strength;
varying vec2 vUv;
// Recursively constructed 4x4 Bayer matrix, with no dynamic array indexing.
float bayer2(vec2 p) {
  if (p.y < 1.0) return p.x < 1.0 ? 0.0 : 2.0;
  return p.x < 1.0 ? 3.0 : 1.0;
}
void main() {
  vec2 size = max(uResolution, vec2(1.0));
  vec2 uv = clamp(vUv, 0.5 / size, 1.0 - 0.5 / size);
  vec3 original = texture2D(uOriginal, uv).rgb;
  vec3 color = texture2D(uInput, uv).rgb;
  vec2 cell = mod(floor(vUv * size / max(float(patternSize), 1.0)), 4.0);
  float threshold = (4.0 * bayer2(mod(cell, 2.0)) + bayer2(floor(cell / 2.0)) + 0.5) / 16.0 - 0.5;
  float steps = max(float(levels) - 1.0, 1.0);
  color = floor(clamp(color + strength * threshold / steps, 0.0, 1.0) * steps + 0.5) / steps;
  gl_FragColor = vec4(mix(original, color, intensity), 1.0);
}

precision highp float;
uniform sampler2D uInput;
uniform sampler2D uOriginal;
uniform vec2 uResolution;
uniform float intensity;
uniform float amount;
uniform float direction;
uniform float edgeBias;
varying vec2 vUv;
vec3 sampleImage(vec2 uv) {
  vec2 edge = 0.5 / max(uResolution, vec2(1.0));
  return texture2D(uInput, clamp(uv, edge, 1.0 - edge)).rgb;
}
void main() {
  vec2 size = max(uResolution, vec2(1.0));
  vec3 original = texture2D(uOriginal, clamp(vUv, 0.5 / size, 1.0 - 0.5 / size)).rgb;
  vec2 p = (vUv - 0.5) * size / min(size.x, size.y);
  float bias = mix(1.0, smoothstep(0.0, 0.7, length(p)), edgeBias);
  float angle = direction * 0.01745329252;
  vec2 shift = vec2(cos(angle), sin(angle)) * amount * bias * min(size.x, size.y) * 0.035 / size;
  vec3 color = sampleImage(vUv);
  color.r = sampleImage(vUv + shift).r;
  color.b = sampleImage(vUv - shift).b;
  gl_FragColor = vec4(mix(original, color, intensity), 1.0);
}

precision highp float;
uniform sampler2D uInput;
uniform sampler2D uOriginal;
uniform vec2 uResolution;
uniform float intensity;
uniform int segments;
uniform float rotation;
uniform float centerX;
uniform float centerY;
uniform float zoom;
varying vec2 vUv;
void main() {
  vec2 size = max(uResolution, vec2(1.0));
  vec2 edge = 0.5 / size;
  vec2 center = vec2(centerX, centerY);
  vec2 p = (vUv - center) * size / min(size.x, size.y);
  float wedge = 6.28318530718 / max(float(segments), 2.0);
  float angle = atan(p.y, p.x + 0.0000001) - rotation * 0.01745329252;
  float folded = abs(mod(angle + wedge * 0.5, wedge) - wedge * 0.5);
  vec2 q = length(p) / max(zoom, 0.01) * vec2(cos(folded), sin(folded));
  vec2 uv = center + q * min(size.x, size.y) / size;
  // Mirror extended coordinates, rather than introducing black wedges or wrap seams.
  uv = 1.0 - abs(mod(uv, 2.0) - 1.0);
  vec3 color = texture2D(uInput, clamp(uv, edge, 1.0 - edge)).rgb;
  vec3 original = texture2D(uOriginal, clamp(vUv, edge, 1.0 - edge)).rgb;
  gl_FragColor = vec4(mix(original, color, intensity), 1.0);
}

precision highp float;
uniform sampler2D uInput;
uniform sampler2D uOriginal;
uniform vec2 uResolution;
uniform float intensity;
uniform float radius;
varying vec2 vUv;
void main() {
  vec2 size = max(uResolution, vec2(1.0));
  vec2 edge = 0.5 / size;
  vec3 original = texture2D(uOriginal, clamp(vUv, edge, 1.0 - edge)).rgb;
  vec3 color = vec3(0.0);
  float total = 0.0;
  // A bounded, spatial Gaussian: radius is the outermost tap distance in pixels.
  for (int y = -3; y <= 3; y++) {
    for (int x = -3; x <= 3; x++) {
      vec2 tap = vec2(float(x), float(y));
      float weight = exp(-dot(tap, tap) / 4.5);
      vec2 uv = clamp(vUv + tap * radius / (3.0 * size), edge, 1.0 - edge);
      color += texture2D(uInput, uv).rgb * weight;
      total += weight;
    }
  }
  gl_FragColor = vec4(mix(original, color / total, intensity), 1.0);
}

precision highp float;
uniform sampler2D uInput;
uniform sampler2D uOriginal;
uniform vec2 uResolution;
uniform float uTime;
uniform float intensity;
uniform float frequency;
uniform float displacement;
uniform int blockSize;
uniform float colorSplit;
varying vec2 vUv;
float noise(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
vec3 sampleImage(vec2 uv) {
  vec2 edge = 0.5 / max(uResolution, vec2(1.0));
  return texture2D(uInput, clamp(uv, edge, 1.0 - edge)).rgb;
}
void main() {
  vec2 size = max(uResolution, vec2(1.0));
  vec3 original = texture2D(uOriginal, clamp(vUv, 0.5 / size, 1.0 - 0.5 / size)).rgb;
  float band = floor(vUv.y * size.y / max(float(blockSize), 1.0));
  float tick = floor(uTime * 3.0);
  float phase = fract(uTime * 3.0);
  // Smoothly fade a small subset of horizontal bands; never invert or flash the screen.
  float envelope = smoothstep(0.0, 0.15, phase) * (1.0 - smoothstep(0.65, 1.0, phase));
  float active = frequency <= 0.0 ? 0.0 : step(1.0 - frequency * 0.4, noise(vec2(band, tick + 7.0))) * envelope;
  float offset = (noise(vec2(band + 31.0, tick)) - 0.5) * displacement * 0.16 * active;
  vec2 uv = vUv + vec2(offset, 0.0);
  vec2 split = vec2(colorSplit * active * 0.018, 0.0);
  vec3 color = sampleImage(uv);
  color.r = sampleImage(uv + split).r;
  color.b = sampleImage(uv - split).b;
  gl_FragColor = vec4(mix(original, color, intensity), 1.0);
}

precision highp float;
uniform sampler2D uInput;
uniform sampler2D uOriginal;
uniform vec2 uResolution;
uniform float intensity;
uniform float distortion;
uniform float zoom;
uniform float centerX;
uniform float centerY;
varying vec2 vUv;
void main() {
  vec2 size = max(uResolution, vec2(1.0));
  vec2 edge = 0.5 / size;
  vec2 center = vec2(centerX, centerY);
  vec2 p = (vUv - center) * size / min(size.x, size.y);
  float r2 = dot(p, p);
  // Bounded radial lens response remains positive even at maximum pincushion.
  float radial = 1.0 + distortion * 0.65 * r2 / (1.0 + r2);
  vec2 uv = center + p * radial / max(zoom, 0.01) * min(size.x, size.y) / size;
  vec3 color = texture2D(uInput, clamp(uv, edge, 1.0 - edge)).rgb;
  vec3 original = texture2D(uOriginal, clamp(vUv, edge, 1.0 - edge)).rgb;
  gl_FragColor = vec4(mix(original, color, intensity), 1.0);
}

precision highp float;
uniform sampler2D uInput;
uniform sampler2D uOriginal;
uniform vec2 uResolution;
uniform float intensity;
uniform float warmth;
uniform float tint;
uniform float contrast;
uniform float saturation;
uniform float fade;
varying vec2 vUv;
void main() {
  vec2 size = max(uResolution, vec2(1.0));
  vec2 uv = clamp(vUv, 0.5 / size, 1.0 - 0.5 / size);
  vec3 original = texture2D(uOriginal, uv).rgb;
  vec3 color = texture2D(uInput, uv).rgb;
  color *= vec3(1.0 + warmth * 0.2 + tint * 0.08, 1.0 - tint * 0.16, 1.0 - warmth * 0.2 + tint * 0.08);
  color = (color - 0.5) * contrast + 0.5;
  float luma = dot(color, vec3(0.2126, 0.7152, 0.0722));
  color = mix(vec3(luma), color, saturation);
  color = clamp(color, 0.0, 1.0);
  color += fade * 0.3 * (1.0 - color);
  gl_FragColor = vec4(mix(original, color, intensity), 1.0);
}

precision highp float;
uniform sampler2D uInput;
uniform sampler2D uOriginal;
uniform vec2 uResolution;
uniform float intensity;
uniform float strength;
uniform float radius;
uniform float softness;
uniform vec3 edgeColor;
varying vec2 vUv;
void main() {
  vec2 size = max(uResolution, vec2(1.0));
  vec2 uv = clamp(vUv, 0.5 / size, 1.0 - 0.5 / size);
  vec3 original = texture2D(uOriginal, uv).rgb;
  vec3 color = texture2D(uInput, uv).rgb;
  // Elliptical distance frames landscape and portrait without narrowing the short axis.
  float distance = length((vUv - 0.5) * 2.0) / 1.41421356237;
  float width = max(softness * 0.6, 1.0 / min(size.x, size.y));
  float shade = smoothstep(radius - width, radius + width, distance) * strength;
  color = mix(color, edgeColor, shade);
  gl_FragColor = vec4(mix(original, color, intensity), 1.0);
}

precision highp float;
uniform sampler2D uInput;
uniform sampler2D uOriginal;
uniform vec2 uResolution;
uniform float uTime;
uniform float intensity;
uniform float strength;
uniform float scale;
uniform float speed;
varying vec2 vUv;
void main() {
  vec2 size = max(uResolution, vec2(1.0));
  vec2 edge = 0.5 / size;
  vec2 p = (vUv - 0.5) * size / min(size.x, size.y);
  float t = uTime * speed;
  vec2 waves = vec2(sin(p.y * scale * 6.28318530718 + t * 0.8 + sin(p.x * scale * 3.0 - t * 0.4)),
    sin(p.x * scale * 6.28318530718 - t * 0.65 + sin(p.y * scale * 3.0 + t * 0.3)));
  vec2 uv = vUv + waves * strength * 0.035 * min(size.x, size.y) / size;
  vec3 color = texture2D(uInput, clamp(uv, edge, 1.0 - edge)).rgb;
  vec3 original = texture2D(uOriginal, clamp(vUv, edge, 1.0 - edge)).rgb;
  gl_FragColor = vec4(mix(original, color, intensity), 1.0);
}

precision highp float;
uniform sampler2D uInput;
uniform sampler2D uOriginal;
uniform vec2 uResolution;
uniform float intensity;
uniform int dotSize;
uniform float angle;
uniform bool invert;
varying vec2 vUv;
void main() {
  vec2 size = max(uResolution, vec2(1.0));
  vec2 edge = 0.5 / size;
  float radians = angle * 0.01745329252;
  float c = cos(radians), s = sin(radians);
  mat2 rotation = mat2(c, s, -s, c);
  vec2 screen = rotation * (vUv * size - size * 0.5);
  float spacing = max(float(dotSize), 2.0);
  vec2 cell = floor(screen / spacing) + 0.5;
  vec2 sampleUv = (mat2(c, -s, s, c) * (cell * spacing) + size * 0.5) / size;
  vec3 inkSource = texture2D(uInput, clamp(sampleUv, edge, 1.0 - edge)).rgb;
  float luma = dot(inkSource, vec3(0.2126, 0.7152, 0.0722));
  // Dot area follows ink coverage; a one-pixel feather avoids jagged tiny dots.
  float coverage = invert ? luma : 1.0 - luma;
  float radius = sqrt(clamp(coverage, 0.0, 1.0)) * 0.70710678;
  float distance = length(screen / spacing - cell);
  float feather = 0.5 / spacing;
  float dotMask = 1.0 - smoothstep(radius - feather, radius + feather, distance);
  vec3 color = vec3(invert ? dotMask : 1.0 - dotMask);
  vec3 original = texture2D(uOriginal, clamp(vUv, edge, 1.0 - edge)).rgb;
  gl_FragColor = vec4(mix(original, color, intensity), 1.0);
}

precision highp float;
uniform sampler2D uInput;
uniform sampler2D uOriginal;
uniform vec2 uResolution;
uniform float intensity;
uniform int palette;
varying vec2 vUv;
vec3 ramp(float t, vec3 a, vec3 b, vec3 c, vec3 d) {
  if (t < 0.33333333) return mix(a, b, t * 3.0);
  if (t < 0.66666667) return mix(b, c, (t - 0.33333333) * 3.0);
  return mix(c, d, (t - 0.66666667) * 3.0);
}
void main() {
  vec2 size = max(uResolution, vec2(1.0));
  vec2 uv = clamp(vUv, 0.5 / size, 1.0 - 0.5 / size);
  vec3 original = texture2D(uOriginal, uv).rgb;
  float t = clamp(dot(texture2D(uInput, uv).rgb, vec3(0.2126, 0.7152, 0.0722)), 0.0, 1.0);
  vec3 color;
  if (palette == 1) color = ramp(t, vec3(0.06, 0.015, 0.025), vec3(0.55, 0.07, 0.04), vec3(1.0, 0.45, 0.05), vec3(1.0, 0.95, 0.65));
  else if (palette == 2) color = ramp(t, vec3(0.015, 0.035, 0.12), vec3(0.025, 0.24, 0.48), vec3(0.03, 0.75, 0.72), vec3(0.75, 1.0, 0.92));
  else if (palette == 3) color = vec3(t);
  else color = ramp(t, vec3(0.035, 0.015, 0.12), vec3(0.45, 0.035, 0.72), vec3(0.02, 0.85, 0.8), vec3(1.0, 0.95, 0.45));
  gl_FragColor = vec4(mix(original, color, intensity), 1.0);
}

passes:
precision highp float;
uniform sampler2D uInput;
uniform vec2 uResolution;
uniform float threshold;
varying vec2 vUv;
void main() {
  vec2 edge = 0.5 / max(uResolution, vec2(1.0));
  vec3 color = texture2D(uInput, clamp(vUv, edge, 1.0 - edge)).rgb;
  float brightness = max(color.r, max(color.g, color.b));
  float contribution = max(brightness - threshold, 0.0) / max(1.0 - threshold, 0.001);
  gl_FragColor = vec4(color * contribution, 1.0);
}
precision highp float;
uniform sampler2D uInput;
uniform vec2 uResolution;
uniform float radius;
varying vec2 vUv;
void main() {
  vec2 size = max(uResolution, vec2(1.0));
  vec2 edge = 0.5 / size;
  vec3 sum = vec3(0.0);
  float weights = 0.0;
  // Static ES 1.00 loop, Gaussian sigma = one third of the finite support.
  for (int i = -8; i <= 8; i++) {
    float tap = float(i);
    float weight = exp(-tap * tap / 14.222222);
    vec2 uv = vUv + vec2(tap * radius / 8.0 / size.x, 0.0);
    sum += texture2D(uInput, clamp(uv, edge, 1.0 - edge)).rgb * weight;
    weights += weight;
  }
  gl_FragColor = vec4(sum / weights, 1.0);
}
precision highp float;
uniform sampler2D uInput;
uniform vec2 uResolution;
uniform float radius;
varying vec2 vUv;
void main() {
  vec2 size = max(uResolution, vec2(1.0));
  vec2 edge = 0.5 / size;
  vec3 sum = vec3(0.0);
  float weights = 0.0;
  for (int i = -8; i <= 8; i++) {
    float tap = float(i);
    float weight = exp(-tap * tap / 14.222222);
    vec2 uv = vUv + vec2(0.0, tap * radius / 8.0 / size.y);
    sum += texture2D(uInput, clamp(uv, edge, 1.0 - edge)).rgb * weight;
    weights += weight;
  }
  gl_FragColor = vec4(sum / weights, 1.0);
}

effects.source:
precision highp float;
uniform sampler2D uInput;
uniform sampler2D uOriginal;
uniform vec2 uResolution;
uniform float intensity;
uniform float strength;
varying vec2 vUv;
void main() {
  vec2 edge = 0.5 / max(uResolution, vec2(1.0));
  vec2 uv = clamp(vUv, edge, 1.0 - edge);
  vec3 original = texture2D(uOriginal, uv).rgb;
  vec3 glow = texture2D(uInput, uv).rgb;
  vec3 bloomed = clamp(original + glow * strength, 0.0, 1.0);
  gl_FragColor = vec4(mix(original, bloomed, intensity), 1.0);
}

precision highp float;
uniform sampler2D uInput;
uniform sampler2D uHistory;
uniform bool uHistoryValid;
uniform vec2 uResolution;
uniform float uTime;
uniform float uDelta;
uniform float intensity;
uniform int mode;
uniform float persistence;
uniform float decay;
uniform float displacement;
uniform int blockSize;
varying vec2 vUv;
float blockNoise(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}
void main() {
  vec2 size = max(uResolution, vec2(1.0));
  vec2 edge = 0.5 / size;
  vec3 original = texture2D(uInput, clamp(vUv, edge, 1.0 - edge)).rgb;
  if (!uHistoryValid || uDelta <= 0.0) {
    gl_FragColor = vec4(original, 1.0);
    return;
  }
  float frames = uDelta * 60.0;
  vec2 movement = vec2(sin(uTime * 0.37), cos(uTime * 0.29)) * 0.3;
  if (mode == 1) {
    vec2 block = floor(vUv * size / max(float(blockSize), 1.0));
    float seed = blockNoise(block);
    // Local, slowly changing bounded block motion; never full-screen flashes.
    movement = vec2(sin(seed * 6.283185 + uTime * 0.41),
                    cos(seed * 5.71 + uTime * 0.33)) * (2.0 + seed * 6.0);
  }
  vec2 uv = vUv + movement * displacement * min(frames, 3.0) / size;
  vec3 previous = texture2D(uHistory, clamp(uv, edge, 1.0 - edge)).rgb;
  float retention = pow(max(persistence, 0.000001), frames);
  if (persistence <= 0.0) retention = 0.0;
  float brightness = pow(max(decay, 0.000001), frames);
  if (decay <= 0.0) brightness = 0.0;
  vec3 feedback = mix(original, previous * brightness, retention);
  gl_FragColor = vec4(mix(original, feedback, intensity), 1.0);
}
